import * as T from 'three';
// Artistic compressed sky, not an astronomical ephemeris. Independent of terrain bounds.
export function createMoonEnvironment(){
 const root=new T.Group();root.name='Lunar sky';let n=517;const rand=()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296;};
 const positions=[],colors=[];const axis=new T.Vector3(.85,.1,-.5).normalize(),q=new T.Quaternion().setFromUnitVectors(new T.Vector3(0,1,0),axis);
 for(let i=0;i<14000;i++){let p;if(i<4500){const z=rand()*2-1,a=rand()*Math.PI*2,r=Math.sqrt(1-z*z);p=new T.Vector3(r*Math.cos(a),z,r*Math.sin(a));}else{const a=rand()*Math.PI*2,band=(rand()+rand()+rand()-1.5)*.12;p=new T.Vector3(Math.cos(a),band,Math.sin(a)).normalize().applyQuaternion(q);if(Math.abs(band)<.018&&rand()<.7)continue;}p.multiplyScalar(350);positions.push(...p.toArray());const brightness=i<4500?.3+rand()*.7:.16+rand()*.3;colors.push(brightness*(.8+rand()*.2),brightness*(.8+rand()*.2),brightness);}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('color',new T.Float32BufferAttribute(colors,3));const stars=new T.Points(g,new T.PointsMaterial({fog:false,size:1.1,sizeAttenuation:true,vertexColors:true,transparent:true,opacity:.9,depthWrite:false,toneMapped:false}));root.add(stars);
 const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d'),gradient=ctx.createRadialGradient(32,32,0,32,32,32);gradient.addColorStop(0,'rgba(160,165,195,.6)');gradient.addColorStop(.35,'rgba(105,112,145,.2)');gradient.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);const hazeTexture=new T.CanvasTexture(canvas),hazeGeometry=new T.BufferGeometry();hazeGeometry.setAttribute('position',new T.Float32BufferAttribute(positions.slice(4500*3),3));const haze=new T.Points(hazeGeometry,new T.PointsMaterial({fog:false,map:hazeTexture,size:12,transparent:true,opacity:.045,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}));stars.add(haze);
 const texture=new T.TextureLoader().load('/moon/assets/earth.jpg');texture.colorSpace=T.SRGBColorSpace;
 const earth=new T.Mesh(new T.SphereGeometry(7,64,32),new T.MeshStandardMaterial({map:texture,roughness:.9,emissive:'#1a3555',emissiveIntensity:.16}));earth.position.set(-80,-78,-180);earth.rotation.z=.4;root.add(earth);
 const halo=new T.Mesh(new T.SphereGeometry(7.15,48,24),new T.ShaderMaterial({transparent:true,depthWrite:false,side:T.BackSide,vertexShader:'varying vec3 n; varying vec3 v; void main(){vec4 p=modelViewMatrix*vec4(position,1.);n=normalize(normalMatrix*normal);v=normalize(-p.xyz);gl_Position=projectionMatrix*p;}',fragmentShader:'varying vec3 n; varying vec3 v; void main(){float a=pow(1.-abs(dot(normalize(n),normalize(v))),3.);gl_FragColor=vec4(.15,.5,1.,a*.55);}'}));halo.position.copy(earth.position);root.add(halo);
 return {root,setWorld(planet,mode='day'){const mars=planet==='mars',alien=planet==='alien';stars.visible=!mars||mode==='night';earth.visible=halo.visible=!mars&&!alien;stars.material.opacity=mars?.42:.9;haze.material.opacity=mars?.012:.045;root.name=alien?'Alien sky':mars?'Martian atmosphere':'Lunar sky';},update(seconds,camera){root.position.copy(camera.position);earth.rotation.y=seconds*.001;stars.rotation.y=seconds*.000008;},dispose(){root.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});texture.dispose();hazeTexture.dispose();}};
}
